import sys

def max_value_expression(E, P, M):
    def evaluate(expr, plus, minus):
        if expr.isdigit():
            return int(expr)

        stack = []
        current_number = 0
        sign = 1

        for char in expr:
            if char.isdigit():
                current_number = current_number * 10 + int(char)
            elif char == '(':
                stack.append(sign)
                stack.append(current_number)
                current_number = 0
                sign = 1
            elif char == ')':
                current_number *= sign
                current_number += stack.pop()
                sign = stack.pop()
            elif char == '?':
                if plus > 0:
                    sign = 1
                    plus -= 1
                elif minus > 0:
                    sign = -1
                    minus -= 1

        return current_number

    def maximize(expr, plus, minus):
        if not expr:
            return 0

        if expr[0] == '(' and expr[-1] == ')' and expr.count('(') == 1:
            return maximize(expr[1:-1], plus, minus)

        max_val = float('-inf')
        balance = 0
        start = 0

        for i, char in enumerate(expr):
            if char == '(':
                balance += 1
            elif char == ')':
                balance -= 1

            if char == '?' and balance == 0:
                left_expr = expr[start:i]
                right_expr = expr[i+1:]

                max_left_plus = plus // 2
                max_left_minus = minus // 2

                for left_plus in range(max_left_plus + 1):
                    left_minus = min(left_expr.count('?') - left_plus, minus - max_left_minus)
                    left_val = maximize(left_expr, left_plus, left_minus)

                    right_plus = plus - left_plus
                    right_minus = minus - left_minus
                    right_val = maximize(right_expr, right_plus, right_minus)

                    max_val = max(max_val, left_val + right_val, left_val - right_val)

                start = i + 1

        if max_val == float('-inf'):
            return evaluate(expr, plus, minus)

        return max_val

    return maximize(E, P, M)

input = sys.stdin.read().splitlines()
E = input[0]
P, M = map(int, input[1].split())
print(max_value_expression(E, P, M))
